package com.example.demo.service.impl.user;
import com.example.demo.dto.user.TrainerDTO;import com.example.demo.enums.*;import com.example.demo.mapper.user.TrainerMapper;import com.example.demo.model.user.*;import com.example.demo.repository.schedule.TrainerScheduleRepository;import com.example.demo.repository.user.TrainerRepository;import com.example.demo.service.params.request.user.trainer.CreateTrainerRequest;import com.example.demo.service.user.UserService;import jakarta.persistence.EntityManager;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.Mock;import org.mockito.junit.jupiter.MockitoExtension;import java.time.LocalDate;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class TrainerServiceImplTest{@Mock UserService users;@Mock TrainerRepository trainers;@Mock TrainerMapper mapper;@Mock TrainerScheduleRepository schedules;@Mock EntityManager em;TrainerServiceImpl service;CreateTrainerRequest request;@BeforeEach void setup(){service=new TrainerServiceImpl(users,trainers,mapper,schedules,em);request=new CreateTrainerRequest("t@x.rs",LocalDate.now(),1990,EmploymentStatus.FULL_TIME);}@Test void createAddsRoleAndProfile(){User u=User.builder().id(4).build();when(users.findOrCreateUser(any())).thenReturn(u);when(em.merge(u)).thenReturn(u);when(trainers.save(any())).thenAnswer(i->i.getArgument(0));service.create(request);verify(users).addRole(4,Role.TRAINER);verify(trainers).save(argThat(t->t.getUser()==u));}@Test void updateChangesProfile(){User u=User.builder().email("old").build();Trainer t=Trainer.builder().user(u).build();when(trainers.findById(2)).thenReturn(Optional.of(t));when(trainers.save(t)).thenReturn(t);when(mapper.toDto(t)).thenReturn(new TrainerDTO());service.update(2,request);assertEquals("t@x.rs",u.getEmail());assertEquals(1990,t.getBirthYear());}@Test void deleteCleansSchedulesAndRemovesWholeAccount(){User u=User.builder().id(4).build();Trainer t=Trainer.builder().user(u).build();when(trainers.findById(2)).thenReturn(Optional.of(t));service.delete(2);verify(schedules).deleteByTrainer(t);verify(em).detach(t);verify(users).delete(4);verify(trainers,never()).delete(any());}}
